namespace Ims.Application.Features.Documents;

/// <param name="PurchaseOrderLineNo">Only on a receipt created from a purchase order (<c>POST /api/purchase-orders/{id}/receipt</c>): the <c>lineNo</c> of the purchase order line this line receives. Every line of such a receipt must name one (a save without it is a 400 and the link is kept), the line's product and unit must be the order line's, and the quantities named for one order line must not exceed what remains of it. On any other document it must be left out (a 400 otherwise), and it is a 400 "not available" while the Purchasing module is off. The link itself is never sent and never changes: it is set when the receipt is created.</param>
/// <param name="SalesOrderLineNo">Only on a delivery created from a sales order (<c>POST /api/sales-orders/{id}/delivery</c>): the <c>lineNo</c> of the sales order line this line delivers. Every line of such a delivery must name one (a save without it is a 400 and the link is kept), the line's product and unit must be the order line's, and the quantities named for one order line must not exceed what remains of it. On any other document it must be left out (a 400 otherwise), and it is a 400 "not available" while the Sales module is off. The link itself is never sent and never changes. A delivery carries no price.</param>
/// <param name="ReturnOfLineNo">Only on a return created from a posted document (<c>POST /api/returns</c>): the position (1 to n, in the order the original lines are listed) of the original line this line returns. Every line of such a return must name one (a save without it is a 400 and the link is kept); the line product and unit must be the original line, and the quantities per original line must stay within what can still be returned. Accepted only while the Returns module is on. The cost is never typed: a customer return takes the cost the goods left at, a supplier return the average.</param>
public record DocumentLineInput(Guid ProductId, decimal Qty, Guid? UomId, decimal? UnitCost, string? Remark, int? PurchaseOrderLineNo = null, int? SalesOrderLineNo = null, int? ReturnOfLineNo = null);
